const body = $json.body ?? $json;
const po = typeof body === 'string' ? JSON.parse(body) : body;
return [{ json: { ...po, received_at: new Date().toISOString(), source: 'webhook' } }];

const po = $json;
const required = ['po_number', 'supplier', 'currency', 'total_amount'];
const missing = required.filter(k => po[k] === undefined || po[k] === null || po[k] === '');
const total = Number(po.total_amount);
const threshold = 100000000;
const risk_flags = [...(po.risk_flags || [])];
if (!Number.isFinite(total)) risk_flags.push('INVALID_TOTAL');
if (missing.length) risk_flags.push('MISSING_REQUIRED_FIELD');
if (Number.isFinite(total) && total > threshold) risk_flags.push('AMOUNT_ABOVE_APPROVAL_THRESHOLD');
const requires_approval = risk_flags.includes('AMOUNT_ABOVE_APPROVAL_THRESHOLD') || Number(po.confidence ?? 1) < 0.80;
return [{ json: { ...po, missing_fields: missing, risk_flags: [...new Set(risk_flags)], requires_approval, status: missing.length ? 'REVIEW_REQUIRED' : (requires_approval ? 'PENDING_APPROVAL' : 'VALIDATED'), validation_passed: missing.length === 0 && Number.isFinite(total), approval_threshold: threshold } }];
